INSERT INTO feature VALUES('refactor-issues','workflow','A merged refactoring verdict files its issue','pr-refactoring','implemented','ordinary',NULL,'When a pull request merges, its seat''s `pr:watch` runs `refactor:file`: a `yes` or `maybe` `## Refactoring` verdict with rows becomes a `kind:refactor` issue labelled `status:unsectioned` under the unit''s epic (the area and epic of the issue the pull request closes, else of the issue its branch names), its table under `## Observation` and a `from:` line, or, for a `maybe` whose `Where` an open refactor issue observes, joins that issue; the coordinator is paged, the seat that claims the issue writes its sections, and a second run files nothing.',NULL,'.config/reports/filing.json',NULL,NULL);
